// Retry policy for Cortex calls (N8N-6.2; lib-config cortex_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call is passed on as an error with the number of calls.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.cortex_http;
const NODE = 'Run Cortex job';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// 2xx with a job id = job accepted (status Waiting, or Success when Cortex
// answered from its job cache); anything else is a refusal (4xx: unknown
// analyzer, TLP/PAP above the analyzer's max, bad input).
const r = $input.first().json;
const b = r.body ?? {};
if (r.statusCode >= 200 && r.statusCode < 300 && typeof b.id === 'string') {
  return [{ json: { ok: true, job_id: b.id, status: b.status ?? null, from_cache: b.status === 'Success', run_attempts: r.attempts } }];
}
return [{ json: { ok: false, class: r.statusCode >= 400 && r.statusCode < 500 ? 'cortex_4xx' : 'cortex_error',
  http_status: r.statusCode ?? null, attempts: r.attempts,
  message: `run refused: HTTP ${r.statusCode}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`.slice(0, 500) } }];

// Retry policy for Cortex calls (N8N-6.2; lib-config cortex_http): a
// connection error or HTTP 5xx -> wait and call again; anything else (2xx,
// 4xx) -> passed on. A client timeout is NOT retried here: this call already
// waited the job's whole time budget, so it ends as class `timeout`.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.cortex_http;
const NODE = 'Wait for Cortex report';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const TIMEOUT = /timeout|timed out|ETIMEDOUT|ECONNABORTED/i;
if (thrown && TIMEOUT.test(JSON.stringify(r))) {
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: false,
    timed_out: true, http_status: null, error_code: r.error?.code ?? null,
    message: `no answer within the HTTP timeout (${attempt} calls)` } }];
}
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// waitreport answers when the job ends or atMost has passed: Success (report
// with summary.taxonomies), Failure (analyzer error), or still Waiting /
// InProgress (= timeout here; the job goes on in Cortex).
const r = $input.first().json;
const j = $('Called by a workflow').first().json.job;
const run = $('Interpret run').first().json;
const b = r.body ?? {};
const base = { kind: 'cortex_job_result', key: j.key, dataType: j.dataType, data: j.data, analyzer: j.analyzer,
  job_id: run.job_id, from_cache: run.from_cache };
if (r.statusCode !== 200) {
  return [{ json: { ...base, outcome: 'failed', class: r.statusCode >= 400 && r.statusCode < 500 ? 'cortex_4xx' : 'cortex_error',
    attempts: r.attempts, message: `waitreport: HTTP ${r.statusCode}`.slice(0, 500) } }];
}
if (b.status === 'Success') {
  const tax = b.report?.summary?.taxonomies;
  return [{ json: { ...base, outcome: 'success', status: b.status, taxonomies: Array.isArray(tax) ? tax : [] } }];
}
if (b.status === 'Failure') {
  // The error's last line is the analyzer's own message (earlier lines are often warnings).
  const msg = String(b.errorMessage ?? '').split('\n').filter((l) => l.trim()).pop() ?? '';
  return [{ json: { ...base, outcome: 'failed', class: 'job_failure', status: b.status, attempts: 1, message: msg.slice(0, 500) } }];
}
return [{ json: { ...base, outcome: 'failed', class: 'timeout', status: b.status ?? null, attempts: r.attempts,
  message: `job not finished within ${j.timeout_s} s (status ${b.status}); it goes on in Cortex` } }];

// A call that failed for good (after its retries), or a refused run.
const x = $input.first().json;
const j = $('Called by a workflow').first().json.job;
const run = $('Interpret run').isExecuted ? $('Interpret run').first().json : null;
const cls = x.class ?? (x.timed_out ? 'timeout' : x.retry_exhausted ? 'cortex_unreachable' : 'cortex_error');
return [{ json: { kind: 'cortex_job_result', key: j.key, dataType: j.dataType, data: j.data, analyzer: j.analyzer,
  job_id: run?.job_id ?? null, from_cache: run?.from_cache ?? false, outcome: 'failed', class: cls,
  stage: x.stage ?? 'Run Cortex job', attempts: x.attempts ?? null, http_status: x.http_status ?? null,
  message: x.message ?? null } }];
